class OrderService {
  getCustomerStreet(orderId: string) {
    const order = this.orderRepo.findById(orderId);
    return order.getCustomer().getAddress().getStreetName().toUpperCase();
  }
}

class InvoicePrinter {
  printCountryCode(invoiceId: string) {
    const invoice = this.repo.find(invoiceId);
    return invoice.customer.getAddress().country.code.toUpperCase();
  }
}

